#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniCut Patch 51 - FX node editor / effect editor: made stable and fast

WHY: effects built in the node editor did not work at all. Run for real, 20 of the 23 nodes failed (the compiler never
filled in the picture inputs, quoted text parameters twice, and the real render context has no .t / .dur).

FIXED (render/fxpack/custom.py - compiler, helpers, loader)
* Compiler rewritten: picture and value inputs are wired correctly; choice / colour / text parameters are read correctly;
  every parameter is checked and clamped before it reaches the generated code (an imported .mcfx cannot inject code).
* Graph checks with readable messages: no Output node, a loop, a link between different socket types. An input that is
  not connected uses the original picture (a warning is shown, not an error).
* Mute now works (a muted node passes its first picture through and its other branches are not computed).
* Only nodes that lead to the Output are run. A picture nobody needs any more is released at once (memory).
* The result is always a contiguous BGRA uint8 picture of the right size (the renderer ignores anything else).
* Time / Wave / Noise nodes got the time they need (ctx.t, ctx.gt, ctx.dur) - the real renderer context only has ctx.lt.
* Speed: Hue/Sat per-pixel Python loop -> OpenCV (about 90x faster); Brightness / Invert / Tint use lookup tables;
  the Over node uses the app's own uint8 compositing (about 5x faster); still noise is cached; neutral settings do no work.
* Over now handles a transparent bottom correctly. Chromatic aberration no longer imports a name that does not exist.
* Saving is atomic (temporary file first); reloading removes effects whose file is gone; importing refuses a file that
  cannot compile.

FIXED (workspace/fx_node_editor.py - editor window)
* Opening the editor failed (AttributeError: _build_params_widget) and clicking a node failed in the parameter panel
  (this part is also in Patch 50).
* Effect names that are not ASCII (Thai) all got the same id and overwrote each other. New effects now always get an
  id nobody else uses.
* Links: only matching socket types can be joined, a link that would make a loop is refused, and a connected input can be
  picked up and dropped on empty space to disconnect it.
* Middle-mouse pan raised NameError (QMouseEvent) - replaced; zoom is limited.
* Closing the window with its own X, or a failed save on Back, no longer loses unsaved work silently.
* The Test button uses the real renderer context, shows the time, and lists warnings. A damaged effect file no longer
  crashes the editor and is never overwritten by accident.

NOT in this patch (planned next): slider/keyframe for every node parameter, groups / nested effects, more nodes,
a code node limited to numpy / cv2 / math, live preview inside the editor.

Files changed: minicut/render/fxpack/custom.py, minicut/workspace/fx_node_editor.py
  python Patch/apply_51_stable_fx_editor.py --check      (look only, change nothing)
  python Patch/apply_51_stable_fx_editor.py              (install)
  python Patch/apply_51_stable_fx_editor.py --revert     (put the files back from the backup)
Close MiniCut before installing. The MiniCut Launcher can do all of this for you.
"""
import base64, datetime, hashlib, json, os, py_compile, shutil, sys, zlib
PATCH_NAME = "patch51_stable_fx_editor"
REPLACE = {'minicut/render/fxpack/custom.py': {'base': ['01e12e6556ff9ad4e2c736b685b0b3f0a536c48520532defb56bb590ed442c36'], 'new': 'd8f1dcfa6f7cc53c76cab50d288a99755ee1fda95581509cfd96f606005c8a19'}, 'minicut/workspace/fx_node_editor.py': {'base': ['82cc8daa75690316919163ce485dbab88a7cfa571f1bae8899329b9fef97e4c7', '3b77e347282b2283fb07afb160249be8665645fcf8fe39840adbb146898152a6'], 'new': 'e82830e6bb56dd883ca8c7cd990fc3d821d369e4de4371288bce22b4832c8a8e'}}
NEW_FILES = {}
PAYLOAD = {'minicut/render/fxpack/custom.py': '', 'minicut/workspace/fx_node_editor.py': ''}
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = HERE if os.path.isfile(os.path.join(HERE, "minicut", "app.py")) else (os.path.dirname(HERE) if os.path.isfile(os.path.join(os.path.dirname(HERE), "minicut", "app.py")) else HERE)
BACKUP_ROOT = os.path.join(ROOT, "_patch_backup")


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except OSError: return None
def new_bytes(rel):
    return zlib.decompress(base64.b64decode(PAYLOAD[rel]))
def latest_backup():
    found = []
    if os.path.isdir(BACKUP_ROOT):
        for d in os.listdir(BACKUP_ROOT):
            mf = os.path.join(BACKUP_ROOT, d, "MANIFEST.json")
            if os.path.isfile(mf):
                try:
                    with open(mf, encoding="utf-8") as f:
                        if json.load(f).get("patch") == PATCH_NAME: found.append(d)
                except Exception: pass
    return os.path.join(BACKUP_ROOT, sorted(found)[-1]) if found else None


def revert():
    bdir = latest_backup()
    if not bdir: print("No backup of this update was found."); return 1
    with open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8") as f: m = json.load(f)
    for rel in m.get("replaced", []): shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in m.get("created", []):
        try: os.remove(path_of(rel))
        except OSError: pass
    os.replace(os.path.join(bdir, "MANIFEST.json"), os.path.join(bdir, "MANIFEST.undone.json"))
    print("Reverted from backup:", bdir); return 0


def main():
    if not os.path.isfile(os.path.join(ROOT, "minicut", "app.py")):
        print("ERROR: the MiniCut folder was not found. Put this file in MiniCut/Patch/ (or next to the minicut folder)."); return 2
    if "--revert" in sys.argv: return revert()
    todo_replace, todo_new, already = [], [], 0
    for rel, h in REPLACE.items():
        cur = read(rel)
        if cur is None: print("STOPPED: missing file", rel, "- no files were changed."); return 3
        c = norm_hash(cur); bases = h["base"] if isinstance(h["base"], (list, tuple)) else [h["base"]]
        if c == h["new"]: already += 1
        elif c in bases: todo_replace.append(rel)
        else:
            print("STOPPED:", rel, "is not the version this update expects (it was changed by hand or by another update).")
            print("No files were changed. This protects your own edits."); return 3
    for rel, text in NEW_FILES.items():
        cur = read(rel)
        if cur is None: todo_new.append(rel)
        elif norm_hash(cur) == norm_hash(text.encode("utf-8")): already += 1
        else: print("STOPPED:", rel, "already exists with other content. No files were changed."); return 3
    if not todo_replace and not todo_new: print("This update is already installed."); return 0
    if "--check" in sys.argv:
        print("Check passed. Would change:", ", ".join(todo_replace + todo_new)); return 0
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); k = 1
    while os.path.exists(bdir): k += 1; bdir = os.path.join(BACKUP_ROOT, "%s_%d" % (stamp, k))      # two installs in one second
    os.makedirs(bdir, exist_ok=False)
    for rel in todo_replace:
        dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(path_of(rel), dst)
    with open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8") as f:
        json.dump({"patch": PATCH_NAME, "created": todo_new, "replaced": todo_replace}, f, indent=2)
    try:
        for rel in todo_replace:
            cur = read(rel); data = new_bytes(rel).replace(b"\r\n", b"\n")
            if b"\r\n" in cur: data = data.replace(b"\n", b"\r\n")            # keep the file's own line endings
            with open(path_of(rel), "wb") as f: f.write(data)
            if norm_hash(read(rel)) != REPLACE[rel]["new"]: raise RuntimeError("hash mismatch after writing " + rel)
        for rel in todo_new:
            os.makedirs(os.path.dirname(path_of(rel)), exist_ok=True)
            with open(path_of(rel), "wb") as f: f.write(NEW_FILES[rel].encode("utf-8"))
        for rel in todo_replace + todo_new:
            if rel.endswith(".py"): py_compile.compile(path_of(rel), doraise=True)
    except Exception as ex:
        for rel in todo_replace: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
        for rel in todo_new:
            try: os.remove(path_of(rel))
            except OSError: pass
        print("ERROR: the update failed and every file was put back:", repr(ex)); return 1
    print("Installed Patch 51. Changed:", ", ".join(todo_replace + todo_new)); print("Backup:", bdir); return 0


if __name__ == "__main__":
    try: code = main()
    except Exception as ex: print("Unexpected error:", repr(ex)); code = 1
    sys.exit(code)
